int uart_init(){
  Config = XUartPs_LookupConfig(XUARTPS_BASEADDRESS);
	if (NULL == Config) {
		return XST_FAILURE;
	}

	Status = XUartPs_CfgInitialize(&Uart_Ps, Config, Config->BaseAddress);
	if (Status != XST_SUCCESS) {
		return XST_FAILURE;
	}
	XUartPs_SetBaudRate(&Uart_Ps, 115200);
  return XST_SUCCESS;
}

void uart_sync(){ // Adapter en fonction du code pyhton 
  while(XUartPs_RecvByte(UART_BASE) != 0xAB){}
  
  // Confirmation de la synchro
  XUartPs_SendByte(UART_BASE, 0xCD);
  
  // Suppression des 0x1B en trop
  while(XUartPs_IsReceiveData(UART_BASE)){
    (void)XUartPs_RecvByte(UART_BASE);
  }
  
}

void uart_recv(u8 *dst, u32 n){
  for (u32 i = 0; i< n; i++) {
    dst[i] = XUartPs_RecvByte(UART_BASE);
  }
}

void uart_send(const u8 *src,u32 n){
  for (u32 i = 0; i< n; i++) {
    XUartPs_SendByte(UART_BASE,src[i]);
  }
}


